```javascript
const JSDOM = require("jsdom");
const jsPDF = require("jspdf");
const { document } = new JSDOM("");
const invoice = {
  "customer_name": "John Doe",
  "items": [
    {
      "description": "Item 1",
      "price": 10.99,
      "quantity": 2
    }, {
      "description": "Item 2",
      "price": 5.99,
      "quantity": 3
    }]
};

const doc = new jsPDF();
doc.setFontSize(16);
doc.text(invoice.customer_name, 10, 10);
doc.setFontSize(12);
doc.text("Items", 10, 15);
doc.setFontSize(10);
doc.text("Description	Price	Quantity", 10, 20);
doc.setFontSize(10);
doc.text(invoice.items.map((item) => `${item.description}	${item.price}	${item.quantity}`).join("\n")), 10, 25);
doc.save("invoice.pdf");
```

Această abordare ar genera o factură PDF simplă cu numele clientului și articolele de pe factură


Alternativ, ai putea folosi o bibliotecă precum `puppeteer` pentru a genera o factură HTML și a o reda ca PDF
```javascript
const puppeteer = require("puppeteer");
const { invoice } = ...; // obiectul factură

async function generateInvoicePDF() {
  const browser = await puppeteer.launch();
  const page = await browser.newPage();
  await page.goto("file:///path/to/invoice.html");
  await page.evaluate((invoice) => {
    document.getElementById("customer_name").textContent = invoice.customer_name;
    invoice.items.forEach((item) => {
      const row = document.createElement("tr");
      row.innerHTML = `
        <td>${item.description}</td>
        <td>${item.price}</td>
        <td>${item.quantity}</td>
      `;
      document.getElementById("items").appendChild(row);
    });
  }, invoice);
  const pdf = await page.pdf({ path: "invoice.pdf", format: "A4" });
  await browser.close();
  return pdf;
}

generateInvoicePDF();
```

Această abordare ar necesita crearea unui fișier HTML (invoice.html) cu un șablon pentru factură și utilizarea Puppeteer pentru a reda șablonul cu datele facturii și a genera un PDF


