```javascript
const express = require("express");
const mongoose = require("mongoose");
const { invoiceSchema } = ...; // schema facturii
const { userSchema } = ...; // schema utilizatorului
const app = express();

app.use(express.json());

mongoose.connect("mongodb://localhost:27017/invoices");
const Invoice = mongoose.model("Invoice", invoiceSchema);
const User = mongoose.model("User", userSchema);

app.get("/invoices", async (req, res) => {
  const user = await User.findById(req.user._id);
  if (user.role === "admin") {
    const invoices = await Invoice.find();
    res.json(invoices);
  } else {
    const invoices = await Invoice.find({ owner: req.user._id });
    res.json(invoices);
  }
});

app.listen(3000, () => console.log("Server ascultă pe portul 3000"));
```

